// @ts-nocheck — generated by design/port-train.py from design/p3-train-bg.html (the design page is the source of truth).
/**
 * The P3R night-train background: a pseudo-3D carriage seen side-on, the
 * workspace's own scenery passing outside, a dot-matrix sea whose dots never
 * move (only breathe), and a dot-matrix whale that breaches as a rare egg.
 * Purely decorative: aria-hidden, no pointer events, no network.
 */
export interface Train {
  setWorkspace(name: string): void
  setDark(on: boolean): void
  summonWhale(): void
  pointer(nx: number, ny: number): void
  dispose(): void
}

export function mountTrain(host: HTMLElement, win: Window): Train {
  const doc = host.ownerDocument
  const root = doc.createElement('div')
  root.className = 'p3r-train'
  root.setAttribute('aria-hidden', 'true')
  root.innerHTML = `<div class="fit"><div class="stage">
    <div class="back"><div class="stars"></div><div class="moon"></div><div class="tower"></div><div class="hills"></div><canvas class="sea" width="1920" height="1200"></canvas></div>
    <div class="grade"></div><div class="grain"></div></div></div>`
  host.prepend(root)
  const q = <T extends Element = HTMLElement>(s: string) => root.querySelector(s) as T
  const fitEl = q('.fit'), stageEl = q('.stage'), gradeEl = q('.grade')
  let rock
  const layer = (rocking = false, cls = '') => { const r = doc.createElement('div'); r.className = 'room ' + cls; rock = doc.createElement('div'); rock.className = rocking ? 'rock' : 'lay'; r.appendChild(rock); stageEl.insertBefore(r, gradeEl); return r }
  const el = (cls, css = '', html = '') => { const d = doc.createElement('div'); d.className = cls; if (css) d.style.cssText = css; d.innerHTML = html; rock.appendChild(d); return d }
  const svgURI = s => `url("data:image/svg+xml,${encodeURIComponent(s)}")`
  const f = n => Math.round(n)
  const reduce = win.matchMedia('(prefers-reduced-motion: reduce)').matches

  const NAVY = '#061565', LIT = '#ffd98a', W = 3600, H = 640;
  const rng = seed => { let s = seed; return () => (s = (s * 9301 + 49297) % 233280) / 233280; };
  const rect = (x, y, w, h, extra = '') => `<rect x="${f(x)}" y="${f(y)}" width="${f(w)}" height="${f(h)}"${extra}/>`;
  const blocks = (r, a, z, o) => { let b = '', l = '', red = ''; let x = a;
    while (x < z) { const w = o.minW + r() * (o.maxW - o.minW), h = o.minH + r() * (o.maxH - o.minH);
      b += rect(x, H - h, w, h);
      for (let yy = H - h + 14; yy < H - 12; yy += o.rowH || 22) for (let xx = x + 8; xx < x + w - 10; xx += 15) if (r() < o.lit) l += rect(xx, yy, 6, 8);
      if (o.antenna && r() < o.antenna) { b += rect(x + w / 2 - 2, H - h - 54, 4, 54); red += `<circle cx="${f(x + w / 2)}" cy="${f(H - h - 56)}" r="5"/>`; }
      x += w + (o.gap || 0) * r(); }
    return { b, l, red }; };
  const svg = (body, lit, extra = '') => svgURI(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><g fill="${NAVY}">${body}</g><g fill="${LIT}" opacity=".85">${lit}</g>${extra}</svg>`);
  const quad = (x0, x1, top, low) => { const c = 2 * low - top; return { d: `M${x0} ${top} Q${(x0 + x1) / 2} ${c} ${x1} ${top}`, y: x => { const t = (x - x0) / (x1 - x0); return (1 - t) ** 2 * top + 2 * (1 - t) * t * c + t * t * top; } }; };

  const backTile = (kind) => { const w = 1200, h = 76, r = rng(kind.length * 17 + 3); let p = '', l = '';
    if (kind === 'skyline' || kind === 'towers') { let x = 0; while (x < w) { const ww = 8 + r() * 26, hh = (kind === 'towers' ? 18 : 6) + r() * (kind === 'towers' ? 56 : 30); p += rect(x, h - hh, ww, hh); if (r() < .5) l += rect(x + ww / 2, h - hh + 4, 2, 2); x += ww + (r() < .3 ? 30 + r() * 120 : 2); } }
    else { const peaks = kind === 'mountains' ? [[0, 420, 64], [380, 360, 50], [700, 520, 70]] : [[0, 260, 40], [230, 190, 24], [450, 350, 56], [790, 150, 20], [940, 260, 44]];
      for (const [x, ww, hh] of peaks) p += `<path d="M${x} ${h} Q${x + ww * .3} ${h - hh} ${x + ww * .55} ${h - hh * .9} T${x + ww} ${h}Z"/>`;
      l += rect(550, 40, 3, 3) + rect(610, 52, 3, 3) + rect(1010, 56, 3, 3); }
    return svgURI(`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><g fill="#071a78">${p}</g><g fill="#ffd98a" opacity=".75">${l}</g></svg>`); };

  const SCENES = {
    bay: { name: '海湾大桥', en: 'BAY BRIDGE', back: 'skyline', build() {
      const deck = H - 170; let b = '', l = '', ex = '';
      for (const tx of [500, 2300]) { b += rect(tx - 18, H - 600, 36, 600) + rect(tx - 34, H - 560, 68, 12) + rect(tx - 34, H - 420, 68, 10) + rect(tx - 28, deck + 18, 56, H - deck); ex += `<circle cx="${tx}" cy="${H - 606}" r="6" fill="#ff4a4a"/>`; }
      b += rect(0, deck, W, 18) + rect(0, deck - 10, W, 3);
      let cables = '';
      for (const [x0, x1] of [[-1300, 500], [500, 2300], [2300, 4100]]) { const q = quad(x0, x1, H - 596, deck - 16); cables += `<path d="${q.d}"/>`;
        for (let x = Math.max(0, x0 + 40); x < Math.min(W, x1 - 30); x += 44) cables += `<line x1="${x}" y1="${f(q.y(x))}" x2="${x}" y2="${deck}"/>`; }
      for (let x = 20; x < W; x += 70) l += `<circle cx="${x}" cy="${deck + 9}" r="3.2"/>`;
      return svg(b, l, `<g fill="none" stroke="${NAVY}" stroke-width="2.5">${cables}</g>${ex}`); } },
    island: { name: '人工岛中央', en: 'ISLAND CENTRAL', back: 'hills', build() {
      const r = rng(11); const a = blocks(r, 0, W, { minW: 60, maxW: 150, minH: 190, maxH: 570, gap: 26, lit: .32, antenna: .25 });
      let b = a.b + rect(0, H - 132, W, 16); for (let x = 40; x < W; x += 300) b += rect(x, H - 116, 20, 116);
      let l = a.l; for (let x = 0; x < W; x += 24) l += rect(x, H - 128, 10, 4);
      return svg(b, l, `<g fill="#ff4a4a">${a.red}</g>`); } },
    school: { name: '学园前', en: 'SCHOOL HILL', back: 'mountains', tower: 'near', build() {
      const r = rng(23); const a = blocks(r, 0, W, { minW: 60, maxW: 120, minH: 50, maxH: 120, gap: 22, lit: .18 });
      // hill crest at H-150 (= 75px of rise); school stands ON the crest, so its base is buried in the hill
      let b = a.b + `<path d="M1050 ${H} Q1850 ${H - 300} 2650 ${H}Z"/>`, l = a.l, ex = '';
      const base = H - 140;
      b += rect(1480, base - 120, 800, 140) + `<path d="M1470 ${base - 120} L1880 ${base - 152} L2290 ${base - 120}Z"/>` + rect(1846, base - 270, 70, 170) + `<path d="M1838 ${base - 270} L1881 ${base - 322} L1924 ${base - 270}Z"/>`;
      for (let row = 0; row < 3; row++) for (let x = 1500; x < 2260; x += 32) if (r() < .55 && (x < 1830 || x > 1930)) l += rect(x, base - 106 + row * 34, 18, 18);
      ex += `<circle cx="1881" cy="${base - 228}" r="21" fill="#e8f2ff"/><path d="M1881 ${base - 228} V${base - 243} M1881 ${base - 228} H1893" stroke="${NAVY}" stroke-width="4"/>`;
      for (let x = 1120; x < 2600; x += 58) { if (x > 1460 && x < 2300) continue; const t = (x - 1050) / 1600; const y = (1 - t) ** 2 * H + 2 * (1 - t) * t * (H - 300) + t * t * H; b += `<circle cx="${x}" cy="${f(y - 18)}" r="${f(20 + r() * 14)}"/>`; }
      return svg(b, l, ex); } },
    arcade: { name: '商店街', en: 'MALL ARCADE', back: 'towers', build() {
      const r = rng(37); const a = blocks(r, 0, W, { minW: 100, maxW: 210, minH: 130, maxH: 290, gap: 6, lit: .35, rowH: 26 });
      const neon = ['#ff4fa0', '#5fe3ff', '#ffe14a', '#b47bff']; let ex = '', x = 0, i = 0;
      while (x < W) { x += 120 + r() * 220; const c = neon[i++ % 4]; if (r() < .5) ex += rect(x, H - 250 + r() * 80, 20, 90 + r() * 50, ` fill="${c}" opacity=".95"`); else ex += rect(x, H - 200 + r() * 60, 90 + r() * 70, 22, ` fill="${c}" opacity=".95"`); }
      // ferris wheel
      const cx = 2700, cy = H - 330, R = 210; let wheel = `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${NAVY}" stroke-width="8"/>`; let rim = '';
      for (let k = 0; k < 16; k++) { const t = k / 16 * Math.PI * 2, px = cx + Math.cos(t) * R, py = cy + Math.sin(t) * R; wheel += `<line x1="${cx}" y1="${cy}" x2="${f(px)}" y2="${f(py)}" stroke="${NAVY}" stroke-width="3"/>`; rim += `<circle cx="${f(px)}" cy="${f(py)}" r="9" fill="${neon[k % 4]}"/>`; }
      wheel += `<path d="M${cx} ${cy} L${cx - 120} ${H} M${cx} ${cy} L${cx + 120} ${H}" stroke="${NAVY}" stroke-width="12"/>`;
      let garland = ''; for (let gx = 0; gx < W; gx += 300) { const q = quad(gx, gx + 300, H - 150, H - 110); garland += `<path d="${q.d}" fill="none" stroke="${NAVY}" stroke-width="2"/>`; for (let k = 1; k < 10; k++) { const xx = gx + k * 30; garland += `<circle cx="${xx}" cy="${f(q.y(xx))}" r="3" fill="${neon[k % 4]}"/>`; } }
      return svg(a.b, a.l, wheel + rim + ex + garland); } },
    dorm: { name: '住宅街', en: 'DORM STREET', back: 'hills', build() {
      const r = rng(51); let b = '', l = '', x = 0;
      while (x < W) {
        if (x > 1300 && x < 1340) { b += rect(1340, H - 250, 440, 250) + rect(1320, H - 262, 480, 14); for (let row = 0; row < 3; row++) for (let wx = 1360; wx < 1760; wx += 46) if (r() < .7) l += rect(wx, H - 230 + row * 70, 26, 34); x = 1820; continue; }
        const w = 90 + r() * 80, h = 70 + r() * 80; b += rect(x, H - h, w, h) + `<path d="M${f(x - 8)} ${f(H - h)} L${f(x + w / 2)} ${f(H - h - 46)} L${f(x + w + 8)} ${f(H - h)}Z"/>`;
        const n = 1 + Math.floor(r() * 3); for (let k = 0; k < n; k++) if (r() < .75) l += rect(x + 14 + k * 30, H - h + 18, 18, 22);
        if (r() < .45) b += `<circle cx="${f(x + w + 18)}" cy="${f(H - 60)}" r="${f(26 + r() * 16)}"/>`; x += w + 26 + r() * 30; }
      let wires = ''; for (let px = 160; px < W; px += 420) { b += rect(px, H - 300, 8, 300) + rect(px - 30, H - 290, 68, 6); const q = quad(px + 4, px + 424, H - 288, H - 250); wires += `<path d="${q.d}"/>`; }
      return svg(b, l, `<g fill="none" stroke="${NAVY}" stroke-width="2">${wires}</g>`); } },
  };
  const TOWER = (() => { let p = '', l = ''; let y = 620, w = 280, k = 0; const r = rng(99);
    while (y > 20) { const h = 40 + r() * 50; const x = (300 - w) / 2 + (r() - .5) * 18; p += `<path d="M${f(x)} ${f(y)} L${f(x + 6)} ${f(y - h)} L${f(x + w - 6)} ${f(y - h + 6)} L${f(x + w)} ${f(y)}Z"/>`;
      for (let wx = x + 14; wx < x + w - 14; wx += 18) if (r() < .35) l += rect(wx, y - h + 12 + r() * (h - 26), 5, 9);
      y -= h; w *= .86; k++; }
    p += `<path d="M138 30 L150 -20 L162 30Z"/>`;
    return `<svg viewBox="0 -30 300 650" preserveAspectRatio="xMidYMax meet"><g fill="#010d05" stroke="#9dff6a" stroke-width="2.5" stroke-opacity=".9">${p}</g><g fill="#b6ff6b">${l}</g></svg>`; })();

  q('.tower').innerHTML = TOWER

  const cityRoom = layer(false, 'outside'); const cityEl = el('city', '', '<i></i>').firstChild
  const whaleCv = doc.createElement('canvas'); whaleCv.className = 'whalecv'; whaleCv.width = 1920; whaleCv.height = 1200; stageEl.insertBefore(whaleCv, gradeEl)
  layer(false, 'outside'); el('wires')
  layer(false, 'outside'); for (let i = 0; i < 3; i++) el('pole', '', `<i style="animation-delay:${-i * .8}s"></i>`)
  const tl = doc.createElement('div'); tl.className = 'tlights'; stageEl.insertBefore(tl, gradeEl)
  layer(true)
  const rr = (x, y, w, h, r) => `M${x + r} ${y}H${x + w - r}Q${x + w} ${y} ${x + w} ${y + r}V${y + h - r}Q${x + w} ${y + h} ${x + w - r} ${y + h}H${x + r}Q${x} ${y + h} ${x} ${y + h - r}V${y + r}Q${x} ${y} ${x + r} ${y}Z`;
  const wins = [[320, 520], [940, 520], [1900, 520], [2520, 520], [3480, 520], [4100, 520]];
  const doors = [[0, 260], [1540, 280], [3120, 280], [4700, 280]];
  const doorWins = doors.flatMap(([x, w]) => [[x + 28, 80], [x + w / 2 + 12, 80]]);
  let holes = '', frames = '', deco = '';
  for (const [x, w] of wins) { holes += rr(x, 140, w, 440, 34); frames += `<path d="${rr(x - 14, 126, w + 28, 468, 44)}" fill="none" stroke="var(--frame)" stroke-width="10"/><path d="${rr(x - 2, 138, w + 4, 444, 36)}" fill="none" stroke="var(--frame-in)" stroke-width="6"/><path d="M${x + 30} 128 H${x + w - 30}" stroke="var(--edge)" stroke-width="3" opacity=".8"/>`; }
  for (const [x, w] of doorWins) { holes += rr(x, 170, w, 420, 18); frames += `<path d="${rr(x - 8, 162, w + 16, 436, 24)}" fill="none" stroke="var(--frame)" stroke-width="7"/>`; }
  for (const [x, w] of doors) deco += `<rect x="${x}" y="110" width="${w}" height="890" fill="var(--wall-hi)"/><rect x="${x}" y="110" width="${w}" height="890" fill="none" stroke="var(--frame)" stroke-width="6"/><line x1="${x + w / 2}" y1="110" x2="${x + w / 2}" y2="1000" stroke="#000" stroke-width="4" opacity=".5"/><rect x="${x + 18}" y="920" width="${w - 36}" height="10" fill="var(--edge)" opacity=".7"/>`;
  for (const [a, b] of [[300, 1130], [2240, 3060], [3460, 4640]]) { deco += `<line x1="${a}" y1="80" x2="${b}" y2="80" stroke="var(--edge)" stroke-width="5" opacity=".85"/>`;
    for (let x = a + 40; x < b; x += 160) deco += `<circle cx="${x}" cy="80" r="11" fill="var(--wall)" stroke="var(--edge)" stroke-width="5"/>`; }
  deco += `<circle cx="2280" cy="80" r="15" fill="#fff" stroke="#e8141f" stroke-width="6"/>`;
  deco += `<rect x="0" y="600" width="5200" height="400" fill="var(--wall-lo)"/><line x1="0" y1="600" x2="5200" y2="600" stroke="var(--edge)" stroke-width="4" opacity=".7"/>`;
  for (const [a, b] of [[280, 1500], [1860, 3080], [3440, 4660]]) deco += `<rect x="${a}" y="592" width="${b - a}" height="80" rx="16" fill="var(--seat-hi)"/><rect x="${a}" y="592" width="${b - a}" height="80" rx="16" fill="none" stroke="rgba(255,255,255,.25)" stroke-width="3"/>`;
  el('wall', '', `<svg width="5200" height="1000" viewBox="0 0 5200 1000">
    <defs><linearGradient id="topglow" x2="0" y2="1"><stop offset="0" stop-color="#dff6ff" stop-opacity=".35"/><stop offset="1" stop-color="#dff6ff" stop-opacity="0"/></linearGradient><linearGradient id="wg" x2="0" y2="1"><stop offset="0" stop-color="var(--wall-hi)"/><stop offset=".55" stop-color="var(--wall)"/><stop offset="1" stop-color="var(--wall-lo)"/></linearGradient></defs>
    <path fill="url(#wg)" fill-rule="evenodd" d="M0 0H5200V1000H0Z ${holes}"/>${deco}${frames}<rect width="5200" height="130" fill="url(#topglow)"/></svg>`);
  for (const [x, w] of wins) el('glass', `width:${w}px;height:440px;transform:translate3d(${x - 1700}px,${140 - 520}px,-522px)`);
  for (const [x, w] of doorWins) el('glass', `width:${w}px;height:420px;border-radius:18px;transform:translate3d(${x - 1700}px,${170 - 520}px,-522px)`);
  el('led', '', '<div class="tag">快速</div><div class="run"><span></span></div>');
  el('ceil', '', '<div class="duct" style="top:60px"></div><div class="lamp" style="top:300px"></div><div class="duct" style="top:520px"></div><div class="lamp" style="top:760px"></div>');
  el('floor', '', wins.map(([x, w]) => `<div class="moonlight" style="left:${x + 120}px;width:${w}px"></div>`).join('') + '<div class="sweep"></div>');
  for (const [a, b] of [[280, 1500], [1860, 3080], [3440, 4660]]) {
    el('seatt', `width:${b - a}px;transform:translate3d(${a - 1700}px,150px,-520px) rotateX(90deg)`);
    el('seatf', `width:${b - a}px;transform:translate3d(${a - 1700}px,150px,-360px)`, '<div class="sweep"></div>');
  }

  const HZ = 492, MX = 1310, CYCLE = 14;
  const sctx = q<HTMLCanvasElement>('.sea').getContext('2d'), wctx = whaleCv.getContext('2d');
  const rows = []; { let y = HZ + 3, g = 2.2, i = 0; while (y < 660) { const sx = 3.2 + g * 1.9; rows.push({ y, g, sx, base: Math.min(.45 + g * .3, 5.6), off: (i % 2) * sx / 2, k: Math.PI * 2 / (sx * 9) }); y += g; g *= 1.13; i++; } }
  const WX = 1560, WY = HZ + 34;
  const body = new Path2D('M28 250 C90 132 310 86 480 150 C532 170 566 196 596 204 C616 200 640 180 694 140 C682 176 670 204 676 226 C688 248 698 268 712 300 C670 282 640 262 606 254 C560 284 500 306 420 314 C270 334 110 336 28 250 Z M210 300 C230 360 284 412 380 432 C340 386 316 344 306 306 Z');
  const belly = new Path2D('M70 280 C190 320 360 318 500 290 C400 340 200 352 70 280 Z');
  const KEYS = [[.50, -80, 170, -60], [.60, -36, 8, -50], [.69, 18, -78, -16], [.80, 92, 6, 30], [.90, 142, 180, 56]];
  const ss = (a, b, x) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
  const whaleAt = p => { if (p < KEYS[0][0] || p > KEYS[KEYS.length - 1][0]) return null;
    for (let i = 0; i < KEYS.length - 1; i++) { const [p0, ...a] = KEYS[i], [p1, ...b] = KEYS[i + 1]; if (p <= p1) { const t = ss(p0, p1, p); return a.map((v, j) => v + (b[j] - v) * t); } } };
  const pulses = p => { const out = [];
    const sw = ss(.38, .58, p) * (1 - ss(.6, .64, p)); if (sw > 0) out.push([WX - 40, WY + 6, 0, 120 * (.4 + sw), sw * 1.1, 'swell']);
    for (const [p0, x] of [[.60, WX - 30], [.83, WX + 120]]) { const age = (p - p0) * CYCLE; if (age >= 0 && age < 2.4) out.push([x, WY + 4, 18 + age * 150, 26, (1 - age / 2.4) * 1.4, 'ring']); }
    return out; };
  const PAL = { day: { dot: [110, 190, 255], hi: [235, 248, 255], whale: '#eaf7ff', belly: '#5fe3ff' }, dark: { dot: [120, 230, 110], hi: [235, 255, 200], whale: '#eaffd6', belly: '#b6ff6b' } };
  const S = .42, LX = 360, LY = 240;
  const MASK = (() => { const c = document.createElement('canvas'); c.width = 360; c.height = 225; const x = c.getContext('2d'); x.scale(.5, .5);
    x.fillStyle = '#fff'; x.fill(body); x.fillStyle = '#00f'; x.fill(belly); x.fillStyle = '#000'; x.beginPath(); x.arc(118, 228, 13, 0, 6.2832); x.fill();
    const d = x.getImageData(0, 0, 360, 225).data, m = new Uint8Array(360 * 225);
    for (let i = 0; i < m.length; i++) { const r = d[i * 4], b = d[i * 4 + 2], a = d[i * 4 + 3]; m[i] = a < 128 ? 0 : r > 128 ? 1 : b > 128 ? 2 : 0; }
    return m; })();
  const maskAt = (lx, ly) => { const ix = lx * .5 | 0, iy = ly * .5 | 0; return ix < 0 || iy < 0 || ix >= 360 || iy >= 225 ? 0 : MASK[iy * 360 + ix]; };
  function draw(now, force) {
    const t = now / 1000;
    let p = force ?? (eggStart == null ? -1 : (t - eggStart) / CYCLE);
    if (force == null && p > 1) { eggStart = null; p = -1; }
    const  pal = stageEl.classList.contains('dark') ? PAL.dark : PAL.day, ps = pulses(p);
    sctx.clearRect(0, HZ, 1920, 1200 - HZ);
    const buckets = [new Path2D(), new Path2D(), new Path2D(), new Path2D()], hi = new Path2D();
    rows.forEach((row, i) => {
      const mw = 26 + row.g * 12;
      for (let x = row.off; x < 1920; x += row.sx) {
        const v = .5 + .5 * Math.sin(x * row.k - t * 1.7 + i * .62), v2 = .5 + .5 * Math.sin(x * row.k * .37 + t * .6 - i * .21);
        let a = .16 + .84 * Math.pow(v * .7 + v2 * .3, 1.6);
        for (const [px, py, R, band, str, kind] of ps) { const dx = x - px, dy = (row.y - py) * 4, d = Math.hypot(dx, dy);
          a += kind === 'swell' ? str * Math.max(0, 1 - d / band) : str * Math.max(0, 1 - Math.abs(d - R) / band); }
        const r = row.base * Math.min(a, 1.9); if (r < .25) continue;
        const dm = Math.abs(x - MX); const path = dm < mw && a > .55 ? hi : buckets[Math.min(3, Math.floor(Math.min(a, .99) * 4))];
        path.moveTo(x + r, row.y); path.arc(x, row.y, r, 0, 6.2832);
      }
    });
    const [dr, dg, db] = pal.dot;
    buckets.forEach((b, i) => { sctx.fillStyle = `rgba(${dr},${dg},${db},${.28 + i * .2})`; sctx.fill(b); });
    sctx.fillStyle = `rgb(${pal.hi.join(',')})`; sctx.fill(hi);
    // whale + spray on the fixed 6.5px grid
    wctx.clearRect(WX - 420, HZ - 360, 840, 420);
    const w = whaleAt(p);
    if (w) { const [dx, dy, rot] = w, ang = rot * Math.PI / 180, ca = Math.cos(ang), sa = Math.sin(ang), cx = WX + dx, cy = WY + dy, G = 6.5;
      const bodyDots = new Path2D(), bellyDots = new Path2D();
      for (let gy = Math.floor((cy - 200) / G) * G; gy < Math.min(cy + 200, WY + 2); gy += G)
        for (let gx = Math.floor((cx - 200) / G) * G; gx < cx + 200; gx += G) {
          const ux = gx - cx, uy = gy - cy, lx = (ca * ux + sa * uy) / -S + LX, ly = (-sa * ux + ca * uy) / S + LY;
          const m = maskAt(lx, ly); if (!m) continue;
          const tgt = m === 2 ? bellyDots : bodyDots; tgt.moveTo(gx + 2.6, gy); tgt.arc(gx, gy, 2.6, 0, 6.2832); }
      wctx.fillStyle = pal.whale; wctx.fill(bodyDots); wctx.fillStyle = pal.belly; wctx.fill(bellyDots); }
    for (const [p0, x0] of [[.60, WX - 30], [.83, WX + 120]]) { const age = (p - p0) * CYCLE; if (age < 0 || age > 1.1) continue;
      const spray = new Path2D(); for (let k = 0; k < 16; k++) { const vx = (k - 7.5) * 14, vy = -150 - (k % 3) * 40; const gx = Math.round((x0 + vx * age) / 6.5) * 6.5, gy = Math.round((WY + vy * age + 260 * age * age) / 6.5) * 6.5; if (gy > WY) continue; spray.moveTo(gx + 2.4, gy); spray.arc(gx, gy, 2.4, 0, 6.2832); }
      wctx.fillStyle = pal.whale; wctx.globalAlpha = 1 - age / 1.1; wctx.fill(spray); wctx.globalAlpha = 1; }
  }

  let eggStart = null, eggTimer = 0, raf = 0, last = 0, disposed = false
  const summonWhale = () => { if (eggStart == null) eggStart = win.performance.now() / 1000 - .35 * CYCLE }
  const scheduleEgg = () => { eggTimer = win.setTimeout(() => { summonWhale(); scheduleEgg() }, (240 + Math.random() * 360) * 1000) }
  const frame = now => { if (disposed) return; if (!stageEl.classList.contains('paused') && now - last > 33) { draw(now); last = now } raf = win.requestAnimationFrame(frame) }

  /* --- workspace -> scenery; the LED board only names the workspace --- */
  const ORDER = ['bay', 'island', 'school', 'arcade', 'dorm']
  const sceneFor = ws => ORDER[[...ws].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7) % ORDER.length]
  const cache = {}
  let curWs = '', tunnelA = 0, tunnelB = 0
  const setLed = () => { const dark = stageEl.classList.contains('dark'), name = curWs || 'DSH'
    q('.led .tag').textContent = dark ? '影时' : '快速'
    const span = q('.led .run span'); span.textContent = dark ? `影时间 DARK HOUR 0:00　·　${name}　·　本列车不停靠任何站` : `次は ▶ ${name}　·　NEXT STOP: ${name.toUpperCase()}　·　${name}`
    const dur = (span.scrollWidth + 880) / 110; span.style.animationDuration = `${dur}s`; span.style.animationDelay = `${-dur * .3}s` }
  const applyScene = () => { const key = sceneFor(curWs || 'dsh'), sc = SCENES[key]
    cityEl.style.backgroundImage = cache[key] ||= sc.build()
    q('.hills').style.backgroundImage = backTile(sc.back)
    q('.tower').classList.toggle('far', sc.tower !== 'near'); setLed() }

  const fit = () => { const r = host.getBoundingClientRect(); const s = Math.max(r.width / 1920, r.height / 1200) || 1; fitEl.style.transform = `translate(-50%,-50%) scale(${s})` }
  const ro = new win.ResizeObserver(fit); ro.observe(host); fit()
  applyScene()
  draw(win.performance.now())
  if (!reduce) { raf = win.requestAnimationFrame(frame); scheduleEgg() }

  let ptr = null
  return {
    setWorkspace(name) {
      if (name === curWs) return
      const first = !curWs; curWs = name
      if (first || reduce) { applyScene(); return }
      win.clearTimeout(tunnelA); win.clearTimeout(tunnelB)
      stageEl.classList.add('tunnel'); tunnelA = win.setTimeout(applyScene, 380); tunnelB = win.setTimeout(() => stageEl.classList.remove('tunnel'), 900)
    },
    setDark(on) { if (stageEl.classList.contains('dark') === on) return; stageEl.classList.toggle('dark', on); setLed(); draw(win.performance.now()) },
    summonWhale,
    pointer(nx, ny) { if (reduce) return; const pending = ptr; ptr = [nx, ny]; if (pending) return
      win.requestAnimationFrame(() => { if (!ptr) return; const [x, y] = ptr; ptr = null; const st = stageEl.style
        st.setProperty('--ry', `${17 + x * 5}deg`); st.setProperty('--rx', `${-y * 2.5}deg`); st.setProperty('--tx', `${120 - x * 40}px`); st.setProperty('--mx', `${-x * 14}px`); st.setProperty('--my', `${-y * 8}px`) }) },
    dispose() { disposed = true; win.cancelAnimationFrame(raf); win.clearTimeout(eggTimer); win.clearTimeout(tunnelA); win.clearTimeout(tunnelB); ro.disconnect(); root.remove() },
  }
}
